namespace RollRadar.Api.Training;

// What the diary API receives and returns. Choices travel as the snake_case names stored in the database
// ("no_gi", "competicao", "por_baixo", "bem"...), see Data/TrainingEntities.cs.

/// <summary>A session as the client sends it (POST and PUT). Rolls, tags and the point to fix replace the stored ones.</summary>
/// <param name="Id">Generated by the client; sending it again returns the stored session instead of a copy.</param>
/// <param name="FocusPoint">"Point to fix" for the next sessions; empty removes it.</param>
public record TrainingSessionInput(
    Guid Id,
    DateOnly Date,
    string? Attire,
    string? Format,
    int DurationMinutes,
    string? TechniqueNotes = null,
    IReadOnlyList<string>? Techniques = null,
    int? Sleep = null,
    int? Pain = null,
    int? Energy = null,
    string? FocusPoint = null,
    IReadOnlyList<RollInput>? Rolls = null);

/// <param name="PartnerName">Found again by name ignoring case and accents, created the first time.</param>
/// <param name="Steps">Positions marked in the roll, in order.</param>
/// <param name="Finishes">Submissions either way, in order; none means nobody was submitted.</param>
public record RollInput(
    string? PartnerName = null,
    string? PartnerBelt = null,
    int? DurationMinutes = null,
    string? Notes = null,
    IReadOnlyList<RollStepInput>? Steps = null,
    IReadOnlyList<RollFinishInput>? Finishes = null);

/// <summary>A position marked in a roll; the user's game node for it is created on first use.</summary>
public record RollStepInput(string TechniqueId, string? Side, string? Outcome = "neutro");

/// <summary>A position of the user's game: a "Posições" or "Guardas" technique and a side.</summary>
public record PositionRef(string TechniqueId, string? Side);

/// <param name="ByMe">True for "finalizei", false for "fui finalizado".</param>
/// <param name="TechniqueId">The submission, optional.</param>
/// <param name="Position">Where it came from, optional.</param>
public record RollFinishInput(bool ByMe, string? TechniqueId = null, PositionRef? Position = null);

public record TrainingSession(
    Guid Id,
    DateOnly Date,
    string Attire,
    string Format,
    int DurationMinutes,
    string? TechniqueNotes,
    IReadOnlyList<string> Techniques,
    int? Sleep,
    int? Pain,
    int? Energy,
    string? FocusPoint,
    IReadOnlyList<Roll> Rolls,
    DateTime CreatedAt,
    DateTime UpdatedAt);

public record Roll(
    int Order,
    long? PartnerId,
    string? PartnerName,
    string? PartnerBelt,
    int? DurationMinutes,
    string? Notes,
    IReadOnlyList<RollStep> Steps,
    IReadOnlyList<RollFinish> Finishes);

public record RollStep(long NodeId, string TechniqueId, string Side, string Outcome);

/// <param name="NodeId">Game node of the position it came from; null when not told.</param>
public record RollFinish(bool ByMe, string? TechniqueId, long? NodeId, PositionRef? Position);

/// <summary>Filters of the history; all optional.</summary>
/// <param name="Query">Text in the technique notes or in the notes of a roll.</param>
public record TrainingFilter(
    DateOnly? From = null,
    DateOnly? To = null,
    long? PartnerId = null,
    string? Format = null,
    string? Attire = null,
    string? Query = null,
    int Page = 1,
    int PageSize = 20);

/// <summary>A page of the history, newest first.</summary>
public record TrainingPage(IReadOnlyList<TrainingSession> Items, int Total, int Page, int PageSize);

public record Partner(long Id, string Name, string? Belt);

/// <summary>An open "point to fix".</summary>
public record FocusPoint(long Id, string Text, Guid OriginSessionId, DateOnly OriginDate, DateTime CreatedAt);

/// <param name="SessionId">Session the point was worked on, when answered while recording one.</param>
public record FocusReviewInput(string? Review, Guid? SessionId = null);

/// <summary>A position of the user's game; <paramref name="LastUsed"/> is null until marked in a roll.</summary>
public record GameNode(long Id, string TechniqueId, string? Label, string Side, bool Hidden, DateOnly? LastUsed, int Uses);

public record CatalogPosition(string TechniqueId, string English, string Portuguese, string Category);

/// <summary>The user's positions, most recently used first, and the catalog positions to add new ones from.</summary>
public record RecentPositions(IReadOnlyList<GameNode> Recent, IReadOnlyList<CatalogPosition> Catalog);

/// <summary>Everything the user has on the site, for GET /api/conta/exportar.</summary>
public record AccountExport(
    DateTime ExportedAt,
    Guid UserId,
    string? Email,
    string? Name,
    IReadOnlyList<TrainingSession> Sessions,
    IReadOnlyList<Partner> Partners,
    IReadOnlyList<GameNode> GameNodes,
    IReadOnlyList<ExportedFocusPoint> FocusPoints);

public record ExportedFocusPoint(long Id, string Text, Guid OriginSessionId, DateTime CreatedAt, string? Review, Guid? ReviewedSessionId);

public enum SaveStatus
{
    Created,
    Updated,

    /// <summary>POST of a session already stored: nothing changed, the stored one is returned.</summary>
    AlreadyExists,

    NotFound,

    /// <summary>The id belongs to someone else's session.</summary>
    Conflict,

    Invalid,
}

public record SaveResult(SaveStatus Status, TrainingSession? Session = null, IDictionary<string, string[]>? Errors = null)
{
    public static SaveResult Invalid(IDictionary<string, string[]> errors) => new(SaveStatus.Invalid, Errors: errors);
}
